    int n = arr.length;
    long[] ans = new long[n];
    for (int w = 1; w <= n; w++) {
        long best = Long.MIN_VALUE;
        for (int s = 0; s + w <= n; s++) {
            long mn = Long.MAX_VALUE;
            for (int k = s; k < s + w; k++) {
                mn = Math.min(mn, arr[k]);
            }
            best = Math.max(best, mn);
        }
        ans[w - 1] = best;
    }
    return ans;
}

