def riddle(self, arr: list[int]) -> list[int]:
    n = len(arr)
    prev_smaller = [0] * n
    next_smaller = [0] * n
    stack: list[int] = []

    for i in range(n):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        prev_smaller[i] = stack[-1] if stack else -1
        stack.append(i)

    stack.clear()
    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] >= arr[i]:
            stack.pop()
        next_smaller[i] = stack[-1] if stack else n
        stack.append(i)

    ans = [0] * (n + 2)
    for i in range(n):
        length = next_smaller[i] - prev_smaller[i] - 1
        ans[length] = max(ans[length], arr[i])

    for w in range(n - 1, 0, -1):
        ans[w] = max(ans[w], ans[w + 1])

    return ans[1:n + 1]

